import {cellName,namedCells} from './data.js?v=179';
import {suspectPortrait,CELL_PROFILES} from './fracture-profiles.js?v=179';
import {recruitmentCandidates,team} from './engine.js?v=179';
import {ACTIONS,COUNTRY} from './data.js?v=179';
import {esc,button,portrait,flag,formatScore} from './ui.js?v=179';
export const MISSION_IMAGES=Object.fromEntries(['travel','drone','arrest','equip','hack','cyberSupport','sneak','contacts','hide','findSafehouse','analyze','rest','surveil','influence','collect','intimidate','authorize','fieldRest','prepare','heal','protect','counter','rescue'].map(k=>[k,`./assets/missions/${k}.webp`]));
MISSION_IMAGES.fieldRest='./assets/missions/field-rest.webp';
export function missionCards(s){return [...(s.turnActivities||[]).filter(r=>r.faction===s.player&&['RÉUSSITE','ÉCHEC','INTERROMPUE'].includes(r.status)).flatMap(r=>r.proofRejection?[r,{...r,type:'forgery'}]:r.condition==='dead'?[r,{...r,type:'death'}]:r.newCapture?[r,{...r,type:'capture'}]:r.newInjury?[r,{...r,type:'injury'}]:[r]),...(s.attackDelayReports||[]),...(s.flightReports||[]).filter(r=>r.faction===s.player&&s.factions[s.player].known[r.suspectId]),...(s.cellReports||[]),...(s.attackReports||[]).filter(r=>!s.plots?.some(p=>p.id===r.plotId&&p.cancelled)&&!s.cellReports?.some(c=>c.attacks.some(p=>p.plotId===r.plotId))),...(s.threatReports||[])];}
export function revealDelay(r){return ['flight','forgery','cell','attack','death','threat','injury','capture','postponement'].includes(r.type)||ACTIONS[r.type]?.safe||r.status==='INTERROMPUE'?0:850;}
export function compactOutcome(r){
 const notes=r.notes||[];
 if(r.status==='INTERROMPUE'){const n=notes.find(n=>/mission close|suspendue|interrompue/i.test(n));return (n||'Conditions de mission devenues invalides.').replace(/^.*? : /,'').split('. ')[0]+'.';}
 if(r.status==='ÉCHEC')return 'Aucune progression.';
 if(r.type==='counter'){const n=notes.filter(n=>n.includes('a repéré')).length;return `Recherche : ${notes.some(n=>n.startsWith('Nouvelle piste :'))?'nouveau dossier découvert':(notes.find(n=>n.includes('progression.'))?.match(/\+[12]/)?.[0]||'0')+' point(s)'} · ${n} agent${n>1?'s':''} repéré${n>1?'s':''}.`;}
 if(r.type==='protect')return `Pays protégé jusqu’à la fin du tour ${r.turn+3}.`;
 if(r.type==='drone'){const count=notes.filter(n=>n.includes('a localisé')).length;return `Accès ouvert · ${count} suspect${count>1?'s':''} localisé${count>1?'s':''} dans le pays.`;}
 if(r.type==='hack'){const proof=notes.some(n=>n.includes('recueillie sur')),research=notes.some(n=>n.startsWith('Nouvelle piste :'))?'nouveau dossier découvert':(notes.find(n=>n.includes('progression.'))?.match(/\+[12]/)?.[0]||'0')+' point(s) de recherche';return `${proof?'Preuve à vérifier':'Aucune preuve supplémentaire'} · hack +1 tour · ${research}.`;}
 if(r.type==='analyze')return notes.some(n=>/falsification|écartée/i.test(n))?'Preuve falsifiée écartée.':'Preuve vérifiée.';
 const labels={collect:'Preuve recueillie.',surveil:'Cible localisée.',prepare:'Arrestation préparée.',arrest:'Cible arrêtée.',drone:'Accès ouvert et reconnaissance terminée.',intimidate:'Renseignements obtenus et cible localisée.',contacts:'Accès ouvert · piste transmise.',authorize:'Mandat obtenu.',influence:'Accès ouvert · coopération mise à jour.',hack:'Renseignements obtenus.',cyberSupport:'Hack d’un pays activé ou prolongé de 3 tours.',findSafehouse:'Planque disponible.',equip:'Arme équipée.',rest:'Repos au QG terminé.',fieldRest:'Repos en planque terminé.',hide:'Discrétion améliorée.',heal:'Blessure soignée.',rescue:'Agent libéré.',travel:'Arrivée à destination.',sneak:'Arrivée clandestine.'};
 return labels[r.type]||'Opération terminée.';
}
export function outcomeMetrics(r){return [['Énergie',-r.fatigue],['Exposition',r.exposure],['Prestige',r.prestige],['Crise',r.crisis]].filter(([,n])=>Number.isFinite(n)&&n!==0).map(([label,n])=>`<span>${label} <b>${n>0?'+':''}${n}</b></span>`).join('');}
export function missionRevealMarkup(r,index,total,revealed=false,agent=null,state=null){
 if(r.type==='postponement')return postponementRevealMarkup(r,index,total);
 if(r.type==='flight')return flightRevealMarkup(r,index,total,state);
 if(r.type==='forgery')return forgeryRevealMarkup(r,index,total);
 if(r.type==='cell')return cellRevealMarkup(r,index,total,state);
 if(['death','threat','injury','capture'].includes(r.type))return alertRevealMarkup(r,index,total,state);
 if(r.type==='attack')return attackRevealMarkup(r,index,total);
 const img=MISSION_IMAGES[r.type],outcome=r.status==='RÉUSSITE'?'success':r.status==='ÉCHEC'?'failure':'interrupted',symbol=outcome==='success'?'✓':outcome==='failure'?'✕':'—';
 const face=revealed?symbol:'20',chance=Number.isFinite(r.chance)?r.chance+' %':'Non consignée';
 return `<section class="mission-reveal compact-action-reveal"><div class="mission-art">${img?`<img src="${img}" alt="${esc(ACTIONS[r.type]?.name||'Mission')}"/>`:'<div class="mission-placeholder">Mission</div>'}<div class="mission-art-caption"><span>DÉBRIEFING / TOUR ${r.turn} · ${index+1} / ${total}</span><h2>${esc(ACTIONS[r.type]?.name||'Aucun ordre')}</h2><p class="result-country" title="${esc(COUNTRY[r.country]?.name||'')}">${COUNTRY[r.country]?flag(r.country):''}</p>${agent?portrait(agent,'debrief-portrait'):''}<h3 class="debrief-agent-name">${esc(r.agent)}</h3></div></div><div class="mission-result ${revealed?'revealed outcome-'+outcome:'waiting'}" aria-live="polite"><div class="mission-chance">Réussite <strong>${chance}</strong>${ACTIONS[r.type]?.safe?' · automatique':''}</div><div class="dice-result"><div class="d20 ${revealed?'settled':'rolling'}" aria-label="Dé à 20 faces${revealed?' : '+esc(r.status):' en mouvement'}"><svg viewBox="0 0 100 110" aria-hidden="true"><path d="M50 3 95 29 95 81 50 107 5 81 5 29Z M50 3 28 39 5 29 M50 3 72 39 95 29 M5 81 28 39 72 39 95 81 50 107 28 39 M72 39 50 107 M5 81 50 76 95 81 M28 39 50 76 72 39"/><text x="50" y="65" text-anchor="middle">${face}</text></svg></div><div>${revealed?`<strong class="mission-outcome"><span class="outcome-icon" aria-hidden="true">${symbol}</span>${esc(r.status)}</strong><p>${r.targetName?'<strong class="result-target">'+esc(r.targetName)+'</strong> ':''}${esc(compactOutcome(r))}</p><div class="outcome-metrics">${outcomeMetrics(r)}</div>${['injured','captured','dead'].includes(r.condition)?'<small class="result-condition">'+({injured:'Agent blessé',captured:'Agent arrêté',dead:'Agent décédé'}[r.condition])+'</small>':''}`:'<strong>Transmission en cours…</strong>'}</div></div></div><div class="reveal-controls">${button(revealed?(index+1===total?'Voir le rapport':'Suivant'):'Révéler maintenant',revealed?'reveal-next':'reveal-now','primary')}${button('Passer au rapport','reveal-skip')}</div></section>`;
}

export function postponementRevealMarkup(r,index,total){
 const country=COUNTRY[r.country],origin=COUNTRY[r.origin],relocated=r.origin!==r.country;
 const reason={flight:'La fuite d’une cible désorganise la cellule.',protection:'La protection du pays perturbe les préparatifs.',relocation:'Fracture a déplacé les préparatifs vers un autre pays.'}[r.reason];
 return `<section class="mission-reveal attack-reveal postponement-reveal"><div class="mission-art"><div class="mission-placeholder">Image à venir</div><div class="mission-art-caption"><span>DÉBRIEFING / TOUR ${r.turn} · ${index+1} / ${total}</span><h2>Attaque reportée</h2><p>${esc(r.kind)}</p></div></div><div class="mission-result revealed outcome-interrupted"><strong class="mission-outcome">Attaque reportée</strong><p>${esc(reason)}</p><div class="attack-details"><p><span>Pays ciblé</span><strong>${flag(r.country)} ${esc(country.name)}</strong></p><p><span>Attaquant</span><strong>Fracture · ${esc(cellName(r.cell))}</strong></p><p><span>Échéance précédente</span><strong>Fin du tour ${r.oldTurn}</strong></p><p><span>Nouvelle échéance</span><strong>Fin du tour ${r.attackTurn}</strong></p>${relocated?`<p><span>Pays précédent</span><strong>${flag(r.origin)} ${esc(origin.name)}</strong></p>`:''}</div><p>${relocated?'La protection reste dans le pays précédent.':'Vérifiez que votre protection couvre la nouvelle échéance.'}</p></div><div class="reveal-controls">${button(index+1===total?'Voir le rapport':'Suivant','reveal-next','primary')}${button('Passer au rapport','reveal-skip')}</div></section>`;
}

export function attackRevealMarkup(r,index,total){
 const stopped=r.status==='INTERCEPTÉE',country=COUNTRY[r.country],title=stopped?'Attaque interceptée':'Attaque réussie';
 return `<section class="mission-reveal attack-reveal"><div class="mission-art"><img src="./assets/missions/${stopped?'attack-intercepted':'attack-hit'}.webp" alt="${title}"/><div class="mission-art-caption"><span>DÉBRIEFING / TOUR ${r.turn} · ${index+1} / ${total}</span><h2>${title}</h2><p>${esc(r.kind)}</p></div></div><div class="mission-result revealed outcome-${stopped?'success':'failure'}"><strong class="mission-outcome">${stopped?'✓':'✕'} ${title}</strong><div class="attack-details"><p><span>Cible</span><strong title="${esc(country.name)}">${flag(r.country)} ${esc(country.city)}</strong></p><p><span>Attaquant</span><strong>Fracture · ${cellName(r.cell)}</strong></p><p><span>Pays participants à la protection</span><strong>${r.participants.length?r.participants.map(f=>`<span title="${esc(COUNTRY[f].name)}" aria-label="${esc(COUNTRY[f].name)}">${flag(f)}</span>`).join(' · '):'Aucun pays — aucune protection active'}</strong></p><p><span>Crise mondiale</span><strong>${r.crisisDelta>0?'+':''}${r.crisisDelta}</strong></p>${stopped&&r.participants.length?`<p><span>Prestige gagné par pays</span><strong>+${formatScore(6/r.participants.length)} point${6/r.participants.length>1?'s':''}</strong></p><p class="muted">6 points partagés entre ${r.participants.length} pays participant${r.participants.length>1?'s':''}.</p>`:''}</div></div><div class="reveal-controls">${button(index+1===total?'Voir le rapport':'Suivant','reveal-next','primary')}${button('Passer au rapport','reveal-skip')}</div></section>`;
}

export function alertRevealMarkup(r,index,total,s){const death=r.type==='death',injury=r.type==='injury',capture=r.type==='capture',title=capture?'Agent arrêté en mission':death?'Agent tué en mission':injury?'Agent blessé en mission':'Nouvelle menace détectée',country=COUNTRY[r.country],canRecruit=death&&s&&!s.ended&&team(s).length+s.recruitments.filter(x=>x.faction===s.player).length<4,candidates=canRecruit?recruitmentCandidates(s):[];
return `<section class="mission-reveal"><div class="mission-art"><img src="./assets/missions/${capture?'agent-captured':death?'agent-death':injury?'agent-injured':'new-threat'}.webp" alt="${title}"><div class="mission-art-caption"><span>DÉBRIEFING / TOUR ${r.turn} · ${index+1} / ${total}</span><h2>${title}</h2><p>${death||injury||capture?esc(r.agent):esc(r.kind)}</p></div></div><div class="mission-result revealed outcome-${death||capture?'failure':'interrupted'}"><h3>${flag(r.country)} ${esc(country.city)}</h3>${capture?`<p>${esc(r.agent)} a été arrêté et est détenu en ${esc(country.name)}.</p><p><strong>Agent indisponible · son poste reste occupé.</strong></p><p>Envoyez un coéquipier dans ce pays et affectez-lui « Extraire un agent capturé » pour le libérer.</p>`:injury?`<p>${esc(r.agent)} a été blessé pendant la mission.</p><p><strong>−10 points aux chances de réussite tant que la blessure n’est pas soignée.</strong></p><p>Faites revenir l’agent au QG et affectez-lui « Recevoir des soins ».</p>`:death?`<p>${esc(r.agent)} est mort en mission. Son poste est vacant.</p>${candidates.length?'<p>Remplaçants tirés au sort · recrutement gratuit · arrivée dans 2 tours.</p>':''}<div class="death-candidates">${candidates.map(a=>`<article>${portrait(a)}<strong>${esc(a.name)}</strong><small>${esc(a.role)}</small>${button('Recruter','hire','small',`data-id="${a.id}"`)}</article>`).join('')}</div>${!canRecruit&&!s?.ended?'<p>La relève est déjà en cours ou les postes sont pourvus.</p>':canRecruit&&!candidates.length?'<p>Aucun remplaçant disponible dans la réserve.</p>':''}`:`<p>Fracture · ${cellName(r.cell)}</p><p>Attaque prévue à la <strong>fin du tour ${r.attackTurn}</strong>.</p><p>Protégez le pays ciblé ou démantelez la cellule avant l’attaque.</p>`}</div><div class="reveal-controls">${button(index+1===total?'Voir le rapport':'Suivant','reveal-next','primary')}${button('Passer au rapport','reveal-skip')}</div></section>`;}

export function resultNote(text){let html=esc(text);for(const c of Object.values(COUNTRY).sort((a,b)=>b.name.length-a.name.length)){html=html.split(esc(c.name)).join(`<span class="result-inline-flag" title="${esc(c.name)}" aria-label="${esc(c.name)}">${flag(c.id)}</span>`);}return html;}

export function cellRevealMarkup(r,index,total,s){
 const suspects=r.suspects.map(id=>s?.suspects.find(t=>t.id===id)).filter(Boolean);
 return `<section class="mission-reveal cell-reveal"><div class="mission-art"><img src="./assets/missions/cell-dismantled.webp" alt="Opérations de la cellule abandonnées"><div class="mission-art-caption"><span>DÉBRIEFING / TOUR ${r.turn} · ${index+1} / ${total}</span><h2>Cellule démantelée</h2><p>${esc(cellName(r.cell))}</p></div></div><div class="mission-result revealed outcome-success"><div class="dismantled-suspects">${suspects.map(t=>`<article>${suspectPortrait({...t,identified:true,arrested:true})}<div><strong>${esc(t.name)}</strong><small>ARRÊTÉ${t.arrestedBy&&COUNTRY[t.arrestedBy]?' · '+esc(COUNTRY[t.arrestedBy].name):''}</small></div></article>`).join('')}</div><h3>${r.attacks.length} attaque${r.attacks.length>1?'s':''} annulée${r.attacks.length>1?'s':''}</h3><ul class="cancelled-attacks">${r.attacks.map(p=>`<li>${flag(p.country)}<div><strong>${esc(COUNTRY[p.country].name)}</strong><span>${esc(p.kind)} · ${esc(cellName(r.cell))}</span></div><small>Prévue T${p.turn}</small></li>`).join('')}</ul>${!r.attacks.length?'<p>Aucune attaque restante à annuler.</p>':''}<p class="muted">Les deux cibles sont en détention. Ces attaques ne pourront plus avoir lieu. Aucun prestige de défense supplémentaire.</p></div><div class="reveal-controls">${button(index+1===total?'Voir le rapport':'Suivant','reveal-next','primary')}${button('Passer au rapport','reveal-skip')}</div></section>`;
}

export function forgeryRevealMarkup(r,index,total){
 const p=r.proofRejection,country=COUNTRY[p.country];
 return `<section class="mission-reveal forgery-reveal"><div class="mission-art"><img src="./assets/missions/forged-proof.png" alt="Examen d’une preuve falsifiée"><div class="mission-art-caption"><span>DÉBRIEFING / TOUR ${r.turn} · ${index+1} / ${total}</span><h2 style="color:#ff767b">Preuve falsifiée</h2></div></div><div class="mission-result revealed outcome-failure"><strong class="mission-outcome">Preuve falsifiée</strong><div class="attack-details"><p><span>Pays du dossier</span><strong>${country?flag(p.country)+' '+esc(country.name):'Non localisé'}</strong></p><p><span>Criminel</span><strong>${esc(p.suspectName)}</strong></p><p><span>Preuve écartée</span><strong>${esc(p.proofName)}</strong></p></div><p>Recueillez une nouvelle preuve avant toute nouvelle préparation ou arrestation. Les missions déjà engagées continuent.</p></div><div class="reveal-controls">${button(index+1===total?'Voir le rapport':'Suivant','reveal-next','primary')}${button('Passer au rapport','reveal-skip')}</div></section>`;
}

export function flightRevealMarkup(r,index,total,s){
 const target=s?.suspects.find(t=>t.id===r.suspectId);
 if(!target||r.faction!==s.player||!s.factions[s.player].known[r.suspectId])return '';
 return `<section class="mission-reveal flight-reveal"><div class="mission-art"><img src="./assets/missions/target-flight.png" alt="Une cible quitte le pays à bord d’un train"><div class="mission-art-caption"><span>DÉBRIEFING / TOUR ${r.turn} · ${index+1} / ${total}</span><h2>Cible en fuite</h2><p>${esc(target.name)} a changé de pays</p></div></div><div class="mission-result revealed outcome-interrupted"><div class="flight-identity">${suspectPortrait({...target,identified:true},'flight-portrait')}<div><span class="eyebrow">DÉPLACEMENT CONFIRMÉ</span><h3>${esc(target.name)}</h3><p>Nouveau pays : <strong>${esc(COUNTRY[r.country].name)}</strong></p></div></div><div class="flight-route" role="img" aria-label="Déplacement de ${esc(COUNTRY[r.origin].name)} vers ${esc(COUNTRY[r.country].name)}"><div>${flag(r.origin)}<small>Départ</small><strong>${esc(COUNTRY[r.origin].name)}</strong></div><svg viewBox="0 0 160 52" aria-hidden="true"><circle cx="9" cy="26" r="5"/><path d="M20 26H138"/><path d="m126 17 12 9-12 9"/><circle cx="151" cy="26" r="5"/></svg><div>${flag(r.country)}<small>Arrivée</small><strong>${esc(COUNTRY[r.country].name)}</strong></div></div><p>Le dossier et les preuves sont conservés. <strong>Localisez à nouveau la cible</strong> avant de procéder à son arrestation.</p></div><div class="reveal-controls">${button(index+1===total?'Voir le rapport':'Suivant','reveal-next','primary')}${button('Passer au rapport','reveal-skip')}</div></section>`;
}
